lessons.example_code:
from abc import ABC, abstractmethod


class Animal(ABC):
    def __init__(self, nombre):
        self.nombre = nombre

    @abstractmethod
    def hablar(self):
        pass

    def __str__(self):
        return f"{self.nombre} dice {self.hablar()}"


class Perro(Animal):
    def hablar(self):
        return "Guau"


class Gato(Animal):
    def hablar(self):
        return "Miau"


for animal in [Perro("Toby"), Gato("Misi")]:
    print(animal)           # polimorfismo

try:
    Animal("Nadie")
except TypeError:
    print("No se puede instanciar una clase abstracta")

